// GET each target once, record status code and response time.
// A Code node (not the HTTP Request node) because the HTTP node can't report response time.
// n8n and the app share a Docker network, so service names work as hostnames.
const targets = [
  { name: 'Frontend', url: 'http://web:8080/' },
  { name: 'API', url: 'http://api:3000/api/tags' },
];
const results = [];
for (const t of targets) {
  const start = Date.now();
  let status = null, error = null;
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: t.url, timeout: 10000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    status = res.statusCode;
  } catch (e) {
    error = e.message; // timeout, connection refused, DNS...
  }
  results.push({ json: { ...t, status, ok: status === 200, ms: Date.now() - start, error, at: new Date().toISOString() } });
}
return results;

// Alert only after 2 failed checks in a row (one blip is ignored); send 'recovered' when back.
// State lives in workflow static data (persists between production runs).
const FAILS_BEFORE_ALERT = 2;
const state = $getWorkflowStaticData('global');
state.targets ??= {}; state.checks ??= []; state.incidents ??= [];
const now = Date.now();
const alerts = [];

for (const { json: r } of $input.all()) {
  const s = (state.targets[r.name] ??= { fails: 0, down: false, downSince: null });
  state.checks.push({ t: now, name: r.name, ok: r.ok, ms: r.ms });
  const why = r.status ? `HTTP ${r.status}` : (r.error ?? 'no response');
  if (!r.ok) {
    s.fails++;
    if (s.fails === FAILS_BEFORE_ALERT && !s.down) {
      s.down = true; s.downSince = now;
      state.incidents.push({ t: now, name: r.name });
      alerts.push(`🔴 **${r.name} is DOWN** (${r.url}): ${why}, failed ${s.fails} checks in a row.`);
    }
  } else {
    if (s.down) alerts.push(`🟢 **${r.name} recovered** (${r.url}): HTTP 200 in ${r.ms} ms after ${Math.max(1, Math.round((now - s.downSince) / 60000))} min down.`);
    s.fails = 0; s.down = false; s.downSince = null;
  }
}

// keep 48 h of history for the daily summary
const cutoff = now - 48 * 3600e3;
state.checks = state.checks.filter((c) => c.t > cutoff);
state.incidents = state.incidents.filter((i) => i.t > cutoff);

return alerts.map((content) => ({ json: { content } })); // no alerts -> no items -> nothing is posted

// Uptime %, average and p95 response time (successful checks), incidents - last 24 h.
const state = $getWorkflowStaticData('global');
const since = Date.now() - 24 * 3600e3;
const checks = (state.checks ?? []).filter((c) => c.t > since);
const names = [...new Set(checks.map((c) => c.name))];

const lines = names.map((name) => {
  const all = checks.filter((c) => c.name === name);
  const up = all.filter((c) => c.ok);
  const ms = up.map((c) => c.ms).sort((a, b) => a - b);
  const avg = ms.length ? Math.round(ms.reduce((a, b) => a + b, 0) / ms.length) : '–';
  const p95 = ms.length ? ms[Math.ceil(ms.length * 0.95) - 1] : '–';
  const incidents = (state.incidents ?? []).filter((i) => i.t > since && i.name === name).length;
  return `**${name}**: uptime ${(100 * up.length / all.length).toFixed(1)}% (${up.length}/${all.length} checks) · avg ${avg} ms · p95 ${p95} ms · incidents ${incidents}`;
});

return [{ json: { content: '📊 **Uptime summary, last 24 h**\n' + (lines.join('\n') || 'No checks recorded yet.') } }];
